import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BoldLowerThirdProps = Record<string, any>;

const BoldLowerThird: React.FC<BoldLowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  primaryText = "WILL SMITH",
  secondaryText = "CREATIVE ACTOR",
  boxColor = "#ffffff",
  primaryTextColor = "#000000",
  secondaryTextColor = "#ffffff",
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Montserrat"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const durationInFrames = Math.round(durationInSeconds * fps);
  const outroStart = durationInFrames - 30; // Start out animation 1 second before end
  const subTextDelay = 15;

  // Animations - Main Box (Horizontal Reveal via Clip Path)
  const boxIntro = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const boxOutro = spring({
    frame: Math.max(0, frame - outroStart),
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  // Combine intro and outro
  const boxProgress = Math.max(0, boxIntro - boxOutro);
  
  // Calculate clip path inset to reveal from center outwards
  const insetX = interpolate(boxProgress, [0, 1], [50, 0]);
  const boxClipPath = `inset(0% ${insetX}% 0% ${insetX}%)`;

  // Animations - Sub Text (Vertical drop and fade)
  const subIntro = spring({
    frame: Math.max(0, frame - subTextDelay),
    fps,
    config: { damping: 12, mass: 0.6 },
  });
  const subOutro = spring({
    frame: Math.max(0, frame - (outroStart - 10)), // Subtext leaves slightly earlier
    fps,
    config: { damping: 12, mass: 0.6 },
  });

  const subProgress = Math.max(0, subIntro - subOutro);
  const subY = interpolate(subProgress, [0, 1], [-30, 0]);
  const subOpacity = interpolate(subProgress, [0.5, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Base sizing logic for responsiveness
  const minDimension = Math.min(width, height);
  const mainFontSize = minDimension * 0.12; // ~130px on 1080p
  const subFontSize = minDimension * 0.035; // ~38px on 1080p

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat", transition: "none" }}>
      
      <div
        style={{
          position: "absolute",
          width: "100%",
          bottom: "15%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        {/* Main Text Container (The White Box) */}
        <div
          style={{
            backgroundColor: boxColor,
            padding: `${minDimension * 0.01}px ${minDimension * 0.03}px`,
            clipPath: boxClipPath,
            WebkitClipPath: boxClipPath,
            zIndex: 2,
            boxShadow: boxProgress > 0.5 ? "0px 10px 30px rgba(0,0,0,0.3)" : "none",
            transition: "none",
          }}
        >
          <div
            style={{
              color: primaryTextColor,
              fontSize: `${mainFontSize}px`,
              fontWeight: 900,
              textTransform: "uppercase",
              letterSpacing: "-0.04em",
              lineHeight: 1,
              margin: 0,
              whiteSpace: "nowrap",
              transition: "none",
              // Slight scale up effect inside the box
              transform: `scale(${interpolate(boxProgress, [0, 1], [0.95, 1])})`,
            }}
          >
            {primaryText}
          </div>
        </div>

        {/* Subtitle Container */}
        <div
          style={{
            zIndex: 1,
            marginTop: `${minDimension * 0.005}px`, // Tight spacing below box
            opacity: subOpacity,
            transform: `translateY(${subY}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              color: secondaryTextColor,
              fontSize: `${subFontSize}px`,
              fontWeight: 800,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
              margin: 0,
              textShadow: "0px 2px 4px rgba(0,0,0,0.5)",
              whiteSpace: "nowrap",
              transition: "none",
            }}
          >
            {secondaryText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BoldLowerThird;